package uk.buzzlab;
import android.app.*; import android.app.job.*; import android.os.Build; import android.os.SystemClock; import android.content.*; import android.util.Log; import org.json.*; import java.io.*; import java.util.*;
/** Sends new drives to the server by itself: after a recording, when the app opens, and again later if it failed. */
public class SyncJob extends JobService {
  static final int ID=77, USER=78, NP=2, NR=3; static long lastN;  static final Object LOCK=new Object(); volatile boolean stop;
  static SharedPreferences ui(Context c){ return c.getSharedPreferences("ui",0); }
  static boolean ready(Context c){ return !ui(c).getString("url","").isEmpty(); }
  static boolean pending(JSONObject m,String url){ return !m.optBoolean("recording")&&!m.optString("syncedPos").equals(url)&&!m.has("syncErr"); }
  static int waiting(Context c){ int n=0; String u=ui(c).getString("url",""); for(JSONObject m:new Store(c).list())if(pending(m,u))n++; return n; }
  /** Ask Android to run the sync once there is a connection. Safe to call often. */
  static void schedule(Context c){ if(!ready(c)||waiting(c)==0)return; JobScheduler js=c.getSystemService(JobScheduler.class); if(js.getPendingJob(ID)!=null)return;
    js.schedule(new JobInfo.Builder(ID,new ComponentName(c,SyncJob.class)).setRequiredNetworkType(ui(c).getBoolean("wifi",false)?JobInfo.NETWORK_TYPE_UNMETERED:JobInfo.NETWORK_TYPE_ANY).setBackoffCriteria(30000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).setPersisted(true).build()); }
  // ---------- notifications
  static void channel(Context c){ c.getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("sync","Uploads",NotificationManager.IMPORTANCE_LOW)); }
  static Notification.Builder nb(Context c,String title,String text){ channel(c); return new Notification.Builder(c,"sync").setSmallIcon(android.R.drawable.stat_sys_upload).setColor(0xFFFF803A).setContentTitle(title).setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setOnlyAlertOnce(true).setContentIntent(PendingIntent.getActivity(c,9,new Intent(c,MainActivity.class).putExtra("tab","sync").addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)); }
  static Notification progressN(Context c,int pct){ return nb(c,"Uploading drives",now.isEmpty()?"Starting":now).setOngoing(true).setProgress(100,Math.max(0,pct),pct<0).build(); }
  /** pct below 0 means not known yet. At most two updates a second. */
  static void progress(Context c,String s,int pct){ boolean stage=pct<0||pct>=100; now=s; long t=SystemClock.elapsedRealtime(); if(!stage&&t-lastN<500)return; lastN=t; try{ c.getSystemService(NotificationManager.class).notify(NP,progressN(c,pct)); }catch(Exception x){} }
  static void result(Context c,String title,String text){ try{ c.getSystemService(NotificationManager.class).notify(NR,nb(c,title,text).setSmallIcon(android.R.drawable.stat_sys_upload_done).setAutoCancel(true).setTimeoutAfter(6*3600*1000L).build()); }catch(Exception x){} }
  static void done(Context c){ now=""; try{ c.getSystemService(NotificationManager.class).cancel(NP); }catch(Exception x){} }
  /** "Sync now": Android keeps this running after the app is left. False if it could not be started. */
  static boolean userNow(Context c){ if(Build.VERSION.SDK_INT<34)return false; try{ JobScheduler js=c.getSystemService(JobScheduler.class); js.cancel(ID); long bytes=0; String u=ui(c).getString("url",""); Store st=new Store(c); for(JSONObject m:st.list())if(pending(m,u))bytes+=new File(st.driveDir(m.optString("id")),"acc.bin").length(); android.net.NetworkRequest nr=new android.net.NetworkRequest.Builder().addCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET).removeCapability(android.net.NetworkCapabilities.NET_CAPABILITY_NOT_VPN).build(); return js.schedule(new JobInfo.Builder(USER,new ComponentName(c,SyncJob.class)).setUserInitiated(true).setRequiredNetwork(nr).setEstimatedNetworkBytes(JobInfo.NETWORK_BYTES_UNKNOWN,Math.max(1,bytes)).build())==JobScheduler.RESULT_SUCCESS; }catch(Exception x){ log(c,"Background upload not available: "+why(x)); return false; } }
  public boolean onStartJob(JobParameters p){ stop=false; if(Build.VERSION.SDK_INT>=34&&p.isUserInitiatedJob())try{ setNotification(p,NP,progressN(this,-1),JobService.JOB_END_NOTIFICATION_POLICY_REMOVE); }catch(Exception x){ log(this,"Notification: "+why(x)); } new Thread(()->{ boolean again=false; try{ again=!run(this,()->stop); }catch(Throwable x){ Log.e("BUZZLAB","SYNC",x); again=true; } jobFinished(p,again&&!stop); }).start(); return true; }
  public boolean onStopJob(JobParameters p){ stop=true; return true; }
  interface Stop { boolean now(); }
  static volatile String now=""; // live progress, empty when idle
  static void note(Context c,String s){ ui(c).edit().putString("syncMsg",s).putLong("syncAt",System.currentTimeMillis()).commit(); log(c,s); }
  static synchronized void log(Context c,String s){ String l=new java.text.SimpleDateFormat("d MMM HH:mm:ss",Locale.UK).format(new Date())+"  "+s+"\n"+ui(c).getString("syncLog",""); String[] q=l.split("\n"); StringBuilder b=new StringBuilder(); for(int i=0;i<Math.min(40,q.length);i++)b.append(q[i]).append('\n'); ui(c).edit().putString("syncLog",b.toString()).commit(); Log.i("BUZZLAB","SYNC "+s); }
  static String why(Throwable x){ String s=x.getClass().getSimpleName()+(x.getMessage()==null?"":": "+x.getMessage()); if(x.getCause()!=null&&x.getCause()!=x)s+=" / "+x.getCause().getClass().getSimpleName()+(x.getCause().getMessage()==null?"":": "+x.getCause().getMessage()); return s.length()>220?s.substring(0,220):s; }
  /** Each step on its own line, so a failure shows where it happened. */
  static String test(Context c){ SharedPreferences ui=ui(c); String u=ui.getString("url",""); StringBuilder o=new StringBuilder(); android.net.ConnectivityManager cm=c.getSystemService(android.net.ConnectivityManager.class); android.net.NetworkCapabilities n=cm.getNetworkCapabilities(cm.getActiveNetwork()); o.append("Network for this app: ").append(n==null?"NONE":(n.hasTransport(android.net.NetworkCapabilities.TRANSPORT_VPN)?"VPN ":"")+(n.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI)?"Wi-Fi ":"")+(n.hasTransport(android.net.NetworkCapabilities.TRANSPORT_CELLULAR)?"mobile data ":"")).append('\n'); int rb=cm.getRestrictBackgroundStatus(); o.append("Data Saver limits this app: ").append(rb==android.net.ConnectivityManager.RESTRICT_BACKGROUND_STATUS_ENABLED?"YES":"no").append('\n'); if(u.isEmpty())return o+"No server set up."; o.append("Server: ").append(u).append("\nLogin saved: ").append(ui.getString("su","").isEmpty()||ui.getString("sp","").isEmpty()?"NO":"yes").append('\n');
    try{ o.append("Address found: ").append(java.net.InetAddress.getByName(new java.net.URL(u).getHost()).getHostAddress()).append('\n'); }catch(Exception x){ return o+"Address lookup FAILED: "+why(x); }
    for(String[] t:new String[][]{{"/healthz","Server answers"},{"/api/cars","Login accepted"}}) try{ java.net.HttpURLConnection h=(java.net.HttpURLConnection)new java.net.URL(u+t[0]).openConnection(); h.setConnectTimeout(10000); h.setReadTimeout(15000); h.setInstanceFollowRedirects(false); if(t[0].startsWith("/api"))h.setRequestProperty("Authorization",auth(ui)); int k=h.getResponseCode(); h.disconnect(); o.append(t[1]).append(": ").append(k==200?"yes":"NO, code "+k+(k==401?" (wrong user name or password)":k==429?" (too many wrong passwords, wait 10 minutes)":"")).append('\n'); if(k!=200)return o.toString(); }catch(Exception x){ return o+t[1]+": FAILED, "+why(x); }
    return o+"Everything works."; }
  static String auth(SharedPreferences ui) throws IOException { return "Basic "+android.util.Base64.encodeToString((ui.getString("su","")+":"+ui.getString("sp","")).getBytes("UTF-8"),android.util.Base64.NO_WRAP); }
  /** True when finished or when retrying can't help; false to try again later. */
  static boolean run(Context c,Stop stop){ synchronized(LOCK){ Store st=new Store(c); SharedPreferences ui=ui(c); String url=ui.getString("url",""); if(url.isEmpty())return true; int ok=0,bad=0,total=waiting(c),at=0; if(total>0)log(c,"Started, "+total+" waiting"); File f=new File(c.getCacheDir(),"sync.zip");
    try{ for(JSONObject m:st.list()){ if(stop.now()){ note(c,"Paused, "+waiting(c)+" waiting"); return false; } if(!pending(m,url))continue; progress(c,"Preparing "+(++at)+" of "+total,-1);
        try(FileOutputStream o=new FileOutputStream(f)){ Io.export(st,Collections.singletonList(m),o,true); }catch(Exception x){ flag(st,m,"syncErr","Couldn't read this drive: "+x.getMessage()); bad++; continue; }
        now="Sending "+at+" of "+total; progress(c,"Sending "+at+" of "+total,0); int code=post(c,url+"/api/upload",ui,f,"Sending "+at+" of "+total); if(code==401||code==403){ note(c,"Wrong user name or password"); result(c,"Upload stopped","Wrong user name or password"); return true; }
        if(code==400||code==413){ flag(st,m,"syncErr","Server refused this drive ("+code+")"); bad++; continue; }
        if(code!=200){ note(c,"Server said "+code+", will try again"); result(c,"Upload paused","Server said "+code+". It will try again."); return false; }
        flag(st,m,"syncedPos",url); ok++; log(c,"Sent drive "+at+" of "+total); }
      note(c,bad>0?"Synced "+ok+", "+bad+" had a problem":ok>0?"Synced "+ok+(ok==1?" drive":" drives"):"Everything is synced"); if(ok>0||bad>0)result(c,bad>0?"Some drives had a problem":"Upload finished",ui.getString("syncMsg","")); return true;
    }catch(Exception x){ note(c,"No connection, will try again. "+why(x)); result(c,"Upload paused","No connection. It will try again."); return false; } finally{ f.delete(); done(c); } } }
  static void flag(Store st,JSONObject m,String k,String v){ try{ if(!st.driveDir(m.getString("id")).exists())return; JSONObject n=new JSONObject(Store.read(new File(st.driveDir(m.getString("id")),"meta.json"))); n.put(k,v); st.saveMeta(n); }catch(Exception x){ Log.w("BUZZLAB","flag "+x); } }
  static int post(Context c0,String u,SharedPreferences ui,File f,String was) throws IOException { java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL(u).openConnection(); try{ c.setConnectTimeout(15000); c.setReadTimeout(120000); c.setInstanceFollowRedirects(false); c.setRequestMethod("POST"); c.setDoOutput(true); c.setFixedLengthStreamingMode(f.length()); c.setRequestProperty("Content-Type","application/zip"); c.setRequestProperty("Authorization",auth(ui)); try(OutputStream o=c.getOutputStream();InputStream in=new FileInputStream(f)){ byte[] q=new byte[65536];int k; long sent=0,all=Math.max(1,f.length()); while((k=in.read(q))>0){ o.write(q,0,k); sent+=k; int pc=(int)(100*sent/all); progress(c0,was+", "+pc+"% of "+String.format(Locale.UK,"%.1f MB",all/1e6),Math.min(99,pc)); } progress(c0,was+", waiting for the server",-1); } return c.getResponseCode(); } finally{ c.disconnect(); } }
}
